<script>export let data; export let form;</script>

<div class="narrow"><a href={'/groups/' + data.group.id}>← Back to {data.group.name}</a><div class="card form-card"><p class="eyebrow">Group settings</p><h1>{data.group.name}</h1>{#if form?.error}<p class="error" role="alert">{form.error}</p>{/if}{#if form?.success}<p class="success" role="status">{form.success}</p>{/if}<section><h2>Group name</h2><form method="POST" action="?/rename"><label>Name<input name="name" value={data.group.name} minlength="2" required /></label><button class="button" type="submit">Save name</button></form></section><section><h2>Members</h2><p class="muted">Remove someone when they should no longer have access to this group.</p><div class="members">{#each data.group.members as member}<div class="member"><span><b>{member.name}</b>{#if member.isCreator}<small>Group creator</small>{/if}</span>{#if !member.isCreator}<form method="POST" action="?/removeMember"><input type="hidden" name="memberId" value={member.id} /><button class="button danger" type="submit">Remove</button></form>{/if}</div>{/each}</div></section></div></div>

<style>.narrow{margin:2rem auto;max-width:650px}.form-card{margin-top:1.5rem}.eyebrow{color:#d26d35;font-weight:800;text-transform:uppercase}.form-card section+section{border-top:1px solid #e6efeb;margin-top:2rem;padding-top:1.5rem}.form-card h2{font-size:1.1rem;margin:0 0 .75rem}.form-card form{display:grid;gap:1rem;margin-top:1rem}.success{background:#e6f2ed;border:1px solid #b8deca;border-radius:8px;color:#146c52;padding:.75rem}.muted,small{color:#58746b}.members{margin-top:1rem}.member{align-items:center;border-top:1px solid #e6efeb;display:flex;justify-content:space-between;padding:.9rem 0}.member span{display:grid;gap:.2rem}.member form{margin:0}.danger{background:#fff0ef;color:#9c332a}@media(max-width:600px){.member{align-items:flex-start;gap:1rem}.member button{padding:.55rem .7rem}}</style>
